using System;
using System.IO;
using CncTrainer.Bridge;

namespace CncTrainer.Tests;

/// <summary>
/// Decodes a byte sequence captured directly from bridge/protocol.py's
/// StateSample.pack() (see the hex literal's generation command in this file's
/// history / PLAN.md) to make sure the C# side actually agrees with the Python
/// side byte-for-byte, not just "round-trips with itself."
/// </summary>
public class ProtocolCrossLanguageTests
{
    // Generated by: python -c "... StateSample(...).pack(seq=777, t_mono_ns=123456789) ..."
    // pos_x=12.5 pos_z=-30.25 vel_x=1.0 vel_z=-2.0 feed_rate=150.0 spindle_rpm=800.0
    // feed_override=1.0 spindle_override=1.0 tool_number=2 tool_nose_radius=0.4
    // spindle_enabled=True task_mode=1 interp_state=0 exec_state=2 motion_line=42
    // estop=False machine_on=True homed_x=True homed_z=True in_cycle=True
    private const string PythonEncodedStatePacketHex =
        "c001090300000000000015cd5b070000000000000000000029400000000000403ec0000000000000f03f" +
        "00000000000000c00000000000c0624000000000000089400000803f0000803f02000000cdcccc3e01" +
        "010002" + "2a000000" + "000101010100";

    [Fact]
    public void Decodes_PythonEncodedStatePacket_Correctly()
    {
        byte[] data = Convert.FromHexString(PythonEncodedStatePacketHex);
        using var ms = new MemoryStream(data);
        using var r = new BinaryReader(ms);

        var header = PacketHeader.Read(r);
        Assert.Equal((byte)PacketType.State, header.PacketType);
        Assert.Equal(777UL, header.Seq);
        Assert.Equal(123456789L, header.TMonoNs);

        var s = StateSample.Read(r);
        Assert.Equal(12.5, s.PosX, precision: 6);
        Assert.Equal(-30.25, s.PosZ, precision: 6);
        Assert.Equal(1.0, s.VelX, precision: 6);
        Assert.Equal(-2.0, s.VelZ, precision: 6);
        Assert.Equal(150.0, s.FeedRate, precision: 6);
        Assert.Equal(800.0, s.SpindleRpm, precision: 6);
        Assert.Equal(1.0f, s.FeedOverride, precision: 4);
        Assert.Equal(1.0f, s.SpindleOverride, precision: 4);
        Assert.Equal(2, s.ToolNumber);
        Assert.Equal(0.4f, s.ToolNoseRadius, precision: 4);
        Assert.True(s.SpindleEnabled);
        Assert.Equal((byte)TaskMode.Auto, s.TaskModeRaw);
        Assert.Equal((byte)InterpState.Idle, s.InterpStateRaw);
        Assert.Equal((byte)2, s.ExecState);
        Assert.Equal(42, s.MotionLine);
        Assert.False(s.Estop);
        Assert.True(s.MachineOn);
        Assert.True(s.HomedX);
        Assert.True(s.HomedZ);
        Assert.True(s.InCycle);
    }

    [Fact]
    public void CommandPacket_RoundTrips_HeaderAndKindAndSeq()
    {
        byte[] packet = CommandPacket.Build(CommandKind.Mdi, seq: 5, clientSeq: 123,
            args: CommandPacket.ArgsMdi("G0 X10"));

        using var ms = new MemoryStream(packet);
        using var r = new BinaryReader(ms);
        var header = PacketHeader.Read(r);
        Assert.Equal((byte)PacketType.Command, header.PacketType);
        Assert.Equal(5UL, header.Seq);

        byte kind = r.ReadByte();
        ulong clientSeq = r.ReadUInt64();
        string mdiText = System.Text.Encoding.UTF8.GetString(r.ReadBytes((int)(ms.Length - ms.Position)));

        Assert.Equal((byte)CommandKind.Mdi, kind);
        Assert.Equal(123UL, clientSeq);
        Assert.Equal("G0 X10", mdiText);
    }
}
